L3_1 = {}
L3_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 4600102
L3_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ENEMY_HAVEN_NULL_A"
L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "응? 이 시커먼 건 뭐야? 이런 게 반입 품목에 있었던가?"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "ん？　この真っ黒なやつはなんだろう？　こんなの搬入リストにあったっけ？"
L3_1.m_Talk_ENG = "Hmm? What's this black thing? Was this also included in the list?"
L3_1.m_Talk_TWN = "嗯？這個黑黑的東西是什麼？搬運清單上有這個嗎？"
L3_1.m_Talk_THA = "หืมม? ไอ้ดำๆ นั่นอะไร? อยู่ในรายชื่อรึเปล่า?"
L3_1.m_Talk_VTN = "Hmm? Thứ đen ngòm này là gì? Nó cũng có trong danh sách sao?"
L3_1.m_Talk_SCN = "呃咦？这个黑乎乎的东西是什么？运进品目中有这种东西吗？"
L3_1.m_Talk_DEU = "Hmm? Was ist das für ein schwarzes Ding? Stand das auch auf der Liste?"
L3_1.m_Talk_FRA = "Hmm ? C'est quoi ce truc noir ? Ça fait partie des marchandises ?"
