L5_1 = {}
L5_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 4600102
L5_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "ENEMY_HAVEN_NULL_B"
L5_1.m_Pos = "R_M_I"
L5_1.m_Talk_KOREA = "무슨 소리야. 품목 확인은 네 담당이잖아."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "何言ってんだよ。リスト確認はお前の仕事だろ？"
L5_1.m_Talk_ENG = "What are you talking about? You were the one in charge of confirming the list."
L5_1.m_Talk_TWN = "你問我幹嘛？清單是你要負責確認的欸！"
L5_1.m_Talk_THA = "พูดอะไรน่ะ? หน้าที่ยืนยันรายชื่อก็ของนายไม่ใช่เหรอ?"
L5_1.m_Talk_VTN = "Cậu đang nói cái gì vậy? Cậu là người chịu trách nhiệm xác nhận danh sách mà."
L5_1.m_Talk_SCN = "你在说什么啊。不是你负责确认品目嘛。"
L5_1.m_Talk_DEU = "Was meinst du? Du warst doch derjenige, der für die Überprüfung der Liste verantwortlich war."
L5_1.m_Talk_FRA = "Qu'est-ce que tu racontes ? C'est pas toi qui devais vérifier la liste ?"
L6_1 = {}
L6_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 4600102
L6_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "ENEMY_HAVEN_NULL_A"
L6_1.m_Pos = "L"
L6_1.m_Talk_KOREA = "알아. 목록에서 본 기억이 없으니까 그렇지."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "そうなんだけど。リストで見た覚えがなくてさ。"
L6_1.m_Talk_ENG = "I know. I'm asking you because I don't remember anything like this on the list."
L6_1.m_Talk_TWN = "我知道，我不記得它有出現在清單上，所以才問你的嘛。"
L6_1.m_Talk_THA = "ก็ใช่ เลยถามเพราะจำไม่ได้ว่ามีอะไรแบบนี้ไง"
L6_1.m_Talk_VTN = "Tôi biết chứ. Tôi đang hỏi cậu bởi vì tôi không nhớ có thứ như thế này."
L6_1.m_Talk_SCN = "我知道。就是因为我不记得在清单上看到过这个才问你的。"
L6_1.m_Talk_DEU = "Ich weiß. Ich kann mich nur nicht daran erinnern, es auf der Liste gesehen zu haben."
L6_1.m_Talk_FRA = "Si, mais justement. Je te demande parce que j'ai pas le souvenir d'avoir vu ce truc-là dedans."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 4600102
L7_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "ENEMY_HAVEN_NULL_B"
L7_1.m_Pos = "R"
L7_1.m_Talk_KOREA = "그냥 어디다 따로 빼놔. 괜히 목록에 없는 거 들여보냈다가 큰일날 수도 있어."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "どっかに出しておけよ。リストにないもの入れて、大変なことになるかもしれないからさ。"
L7_1.m_Talk_ENG = "Just leave it out for now. We might get in trouble for bringing in something that hasn't been on the list."
L7_1.m_Talk_TWN = "先放到其他地方吧，要是把清單上沒有的東西搬進去，到時候又要倒大楣。"
L7_1.m_Talk_THA = "ทิ้งมันไว้ก่อนละกัน เอาอะไรที่ไม่ได้รับอนุมัติเข้าไปงานจะเข้ากันหมด"
L7_1.m_Talk_VTN = "Bỏ lại đã. Chúng ta sẽ gặp rắc rối nếu mang theo thứ chưa được duyệt đấy."
L7_1.m_Talk_SCN = "还是单独放在别的地方吧。把清单上没有的东西运进去，说不定会出大事。"
L7_1.m_Talk_DEU = "Leg es einfach irgendwohin. Wir könnten in Schwierigkeiten geraten, wenn wir etwas reinbringen, das nicht auf der Liste steht."
L7_1.m_Talk_FRA = "Bah, laisse ça ici pour le moment. Si on apporte quelque chose qui n'a pas été approuvé, on pourrait avoir des ennuis."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 4600102
L8_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "ENEMY_HAVEN_NULL_A"
L8_1.m_Pos = "L"
L8_1.m_Talk_KOREA = "고작 그런 걸로 큰일… 나겠네. 요즘 헤론 님 가차없으시니까."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "それくらいで大変なことになるわけ……あるか。最近のヘロン様は容赦ないからな。"
L8_1.m_Talk_ENG = "Get in trouble for this? Yeah... you're right. Madam Heron's ruthless these days…"
L8_1.m_Talk_TWN = "不過就是搬個東西…確實很可能會倒大楣，海倫夫人最近喜怒無常。"
L8_1.m_Talk_THA = "งานจะเข้าเพราะเรื่องนี้เหรอ? เอ้อ... นั่นสินะ ความอำมหิตของมาดามเฮรอนทุกวันนี้นี่..."
L8_1.m_Talk_VTN = "Gặp rắc rối vì thứ này? Yeah. Dạo này quý bà Heron tàn bạo lắm..."
L8_1.m_Talk_SCN = "你说得对，还真的……会出大事。最近海伦大人办事越来越不留情面了。"
L8_1.m_Talk_DEU = "In Schwierigkeiten geraten? Ja, du hast recht. Madame Heron ist heutzutage nämlich echt gnadenlos ..."
L8_1.m_Talk_FRA = "Des ennuis... ? Peut-être que tu as raison, en fait. Ces jours-ci, Madame Heron est intraitable."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 4600102
L9_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ENEMY_HAVEN_NULL_B"
L9_1.m_Pos = "R"
L9_1.m_Talk_KOREA = "헤이븐 형님 닮아가는 거겠지. 간부 중에 제일 오래 같이 일하셨잖아."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "ヘイブン兄貴に似てきてるんだろ。幹部の中でも一番長いんだし。"
L9_1.m_Talk_ENG = "Maybe she's becoming more and more like Mr. Haven. She has been by his side longer than anyone else."
L9_1.m_Talk_TWN = "應該就是越來越像天堂大哥吧，畢竟她是跟在大哥身邊的幹部中，資歷最久的一個。"
L9_1.m_Talk_THA = "เธออาจจะเหมือนคุณแฮฟเวนเข้าทุกวันนะ ก็เธออยู่กับเขามานานกว่าใครนี่"
L9_1.m_Talk_VTN = "Có lẽ bà ấy ngày càng giống ông Haven. Bà ấy đã ở bên cạnh ông ta lâu hơn bất kỳ ai khác."
L9_1.m_Talk_SCN = "应该是越来越像海文老大了吧。毕竟干部当中他们一起共事的时间最长。"
L9_1.m_Talk_DEU = "Sie wird immer mehr wie Boss Haven. Von allen Consiglieres haben die beiden am längsten zusammengearbeitet."
L9_1.m_Talk_FRA = "J'ai l'impression qu'elle ressemble de plus en plus à M. Haven. Faut dire que depuis le temps qu'elle l'accompagne..."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 4600102
