L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "이건 일단 저쪽 컨테이너에 두고, 급한 것들부터 옮기자고."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "とりあえずこれはあっちのコンテナにおいて、急ぎのものから運ぼうぜ。"
L10_1.m_Talk_ENG = "Just leave that over by that container over there, and let's move these first."
L10_1.m_Talk_TWN = "這就先放那邊的貨櫃裡，先搬那些比較急的吧！"
L10_1.m_Talk_THA = "ทิ้งมันไว้ที่คอนเทนเนอร์ตรงนั้นนั่นแหละ มาขนนี่กันก่อน"
L10_1.m_Talk_VTN = "Cứ quăng nó ra chỗ thùng chứa đằng kia,  chúng ta di chuyển mấy thứ này trước đi."
L10_1.m_Talk_SCN = "这个先放到那边的货柜里，先从急用的东西开始搬吧。"
L10_1.m_Talk_DEU = "Lass es uns einfach bei dem Container dort drüben abstellen und zuerst die anderen Sachen reinbringen."
L10_1.m_Talk_FRA = "Bon, laisse ce truc dans le conteneur là-bas, et occupons-nous du reste."
