L25_1 = {}
L25_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 4600102
L25_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "이럴 줄 알았으면 할아버지한테 같이 오자고 할 걸."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "こんなことならおじいちゃんに一緒に行こうって頼めばよかったかな。"
L25_1.m_Talk_ENG = "Should've asked Grandpa to come along if I knew it was going to be like this..."
L25_1.m_Talk_TWN = "早知道就找爺爺一起來。"
L25_1.m_Talk_THA = "รู้งี้น่าขอให้ปู่มาด้วย..."
L25_1.m_Talk_VTN = "Lẽ ra mình nên rủ Ông đi cùng nếu biết mọi chuyện sẽ thế này..."
L25_1.m_Talk_SCN = "早知道这样，我就叫爷爷一起来了。"
L25_1.m_Talk_DEU = "Wenn ich gewusst hätte, dass es so sein würde, hätte ich meinen Opa gebeten, mitzukommen."
L25_1.m_Talk_FRA = "Si j'avais su, j'aurais demandé à papy de m'accompagner..."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@26#Talk"
