L27_1 = {}
L28_1 = 1
L29_1 = 0.25
L27_1[1] = L28_1
L27_1[2] = L29_1
L26_1.m_Bounce = L27_1
L26_1.m_Talk_KOREA = "……아니야, 오늘은 새 친구를 만나는 날이니까!"
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "……ううん、今日は新しい友達と会う日なんだから！"
L26_1.m_Talk_ENG = "No... Today's all about making new friends!"
L26_1.m_Talk_TWN = "……不行，今天是認識新朋友的日子！"
L26_1.m_Talk_THA = "ไม่ได้สิ... วันนี้ต้องหาเพื่อนใหม่นะ!"
L26_1.m_Talk_VTN = "Không... Việc của hôm nay chỉ là kết bạn mới mà thôi!"
L26_1.m_Talk_SCN = "……不不，今天可是我跟新朋友见面的日子！"
L26_1.m_Talk_DEU = "... Nein, heute geht es darum, neue Freunde zu finden!"
L26_1.m_Talk_FRA = "... Non.  Aujourd'hui, je vais essayer de me faire de nouveaux amis !"
L27_1 = {}
L27_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@27#Talk"
L27_1.m_CutScenProcessKey = 27
