L28_1 = {}
L29_1 = 1
L30_1 = 0.25
L28_1[1] = L29_1
L28_1[2] = L30_1
L27_1.m_Bounce = L28_1
L27_1.m_Talk_KOREA = "맞아. 친구들에게 멋진 모습을 보여 주려고 호출기도 안 가져왔잖아.  "
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "そうだよ。友達にカッコいい姿を見せようと思って呼び出し機も持ってこなかったもん。  "
L27_1.m_Talk_ENG = "Right! I didn't even bring my beeper just so I can look cool in front of them!  "
L27_1.m_Talk_TWN = "沒錯，為了在新朋友面前酷一點，我還特地沒帶呼叫器出來呢。"
L27_1.m_Talk_THA = "จริงด้วย! นี่ไม่เอาเพจเจอร์มาจะได้ดูเท่ๆ เลยนะ!  "
L27_1.m_Talk_VTN = "Đúng vậy! Mình thậm chí còn không mang theo máy nhắn tin chỉ để trông thật ngầu trước mặt họ!  "
L27_1.m_Talk_SCN = "没错。为了让朋友们看到我酷酷的样子，我都特意没带传呼机。"
L27_1.m_Talk_DEU = "Genau! Ich habe nicht einmal meinen Pieper mitgebracht, nur damit ich cool aussehen kann!"
L27_1.m_Talk_FRA = "D'ailleurs j'ai même pas pris mon bipeur pour avoir l'air cool !"
L28_1 = {}
L28_1.m_CutScenKey_Talk = "NEVERLAND_ACT1_INTERLUDE1@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 4600102
