L28_1.m_Pos = "R_F_C"
L28_1.m_Talk_KOREA = "<color=#ffd34c>초퍼</color>는 언제 올까? 빨리 만나면 좋겠다."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "<color=#ffd34c>チョッパー</color>はいつ来るのかな？　早く会いたいなぁ。"
L28_1.m_Talk_ENG = "I wonder when <color=#ffd34c>Chopper</color> will show up? I'm so excited!"
L28_1.m_Talk_TWN = "不過<color=#ffd34c>喬巴</color>怎麼還沒來？好想趕快見到她喔。"
L28_1.m_Talk_THA = "สงสัยจัง เมื่อไหร่<color=#ffd34c>ชอปเปอร์</color>จะมานะ? ตื่นเต้นจังอะ!"
L28_1.m_Talk_VTN = "Không biết khi nào thì <color=#ffd34c>Chopper</color> xuất hiện nhỉ? Mình phấn khích quá!"
L28_1.m_Talk_SCN = "<color=#ffd34c>小斧头</color>什么时候来啊？好想快点见面。"
L28_1.m_Talk_DEU = "Ich frage mich, wann <color=#ffd34c>Chopper</color> kommen wird? Ich bin schon so aufgeregt!"
L28_1.m_Talk_FRA = "Est-ce que <color=#ffd34c>Chopper</color> va venir ? Je suis si excitée !"
