L31_1 = "커다란 도끼를 가지고 있을까? 몸집이 쑥쑥 커져도 재밌을 거야."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "大きな斧を持ってるのかな？　身体がぐんぐん大きくなっても面白そう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Will my new friend be holding a giant axe? It'll be fun if she can change her size, too!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "她會帶著大斧頭嗎？身體會變大的話也很有趣欸！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เพื่อนใหม่จะถือขวานอันโตๆ มาด้วยมั้ยนะ? ถ้าเธอเปลี่ยนขนาดมันได้ต้องสนุกแน่เลยอ้ะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Người bạn mới của mình sẽ cầm một chiếc rìu khổng lồ sao? Nếu cơ thể cô ấy có thể biến lớn nhỏ thì càng tuyệt hơn nữa!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "她会拿着大斧头吗？身体一下子变大也很有趣。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wird meine neue Freundin eine riesige Axt mit sich herumtragen? Es wäre auch cool, wenn sie ihre Größe ändern könnte!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mon nouvel ami aura-t-il une hache géante ? Ou bien pourra-t-il changer sa taille à volonté ?"
L30_1.m_Talk_FRA = L31_1
