L38_1 = "어떡하지? 가면이 없어. 가면 없이는……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "どうしよう。仮面がない。仮面がないと……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "What do I do? I don't have my mask. Without it, I'm noth─"
L37_1.m_Talk_ENG = L38_1
L38_1 = "怎麼辦？我的面具呢？沒有面具的話……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ทำไงดีนะ? ไม่มีหน้ากากด้วย ถ้าไม่มีนี่เรา..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Mình làm gì bây giờ? Mình không mang mặt nạ. Không có nó, mình..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "怎么办？没有假面。没有假面，我……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Was soll ich bloß tun? Ich habe meine Maske nicht dabei. Ohne sie kann ich doch nicht ..."
L37_1.m_Talk_DEU = L38_1
