L40_1.m_fTalkTime = 0.03
L41_1 = "どっか痛いの？　私にできることある？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Are you hurt? Do you need help?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "你身體不舒服嗎？需要幫忙嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เจ็บตรงไหนรึเปล่าคะ? ให้ช่วยมั้ย?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cậu đang bị thương sao? Cậu cần giúp chứ?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你哪里不舒服吗？需要我帮忙吗？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Bist du verletzt? Brauchst du Hilfe?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Hé, ça va ? Tu as besoin d'aide ?"
