L45_1 = "ENEMY_HAVEN_NULL_C"
L44_1.m_CharStrID = L45_1
L45_1 = "찾아! 감히 형님 사무실에서 겁도 없이 무전취식을 한 놈이다!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "探せ！　兄貴の事務室で食い逃げしたやつだ！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "FIND HIM! He needs to pay for sneaking into Mr. Haven's office and eating his food!!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "把人找出來！竟敢在大哥辦公室裡目中無人地騙吃騙喝！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หาตัวมันให้เจอ! มันต้องชดใช้ที่แอบเข้าไปในห้องทำงานคุณแฮฟเวนแล้วกินอาหารเขา!!"
L44_1.m_Talk_THA = L45_1
L45_1 = "TÌM THẤY NÓ RỒI! Nó phải trả giá vì lẻn vào văn phòng của ông Haven rồi ăn vụng đồ ăn của ông ấy!!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "快搜！那家伙居然敢在老大的办公室里吃白食！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "FINDET IHN! Dieser Kerl muss dafür bestraft werden, dass er sich in das Büro vom Boss eingeschlichen und sein ganzes Essen verschlungen hat!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Trouvez-le ! Cet insolent a osé se faufiler dans le bureau de M. Haven, et il a même volé son repas !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NEVERLAND_ACT1_INTERLUDE1@45#Talk"
