L46_1 = "ENEMY_HAVEN_NULL_C"
L45_1.m_CharStrID = L46_1
L46_1 = "분명 여기 어딘가에 숨어 있을 거다! 샅샅이 뒤져!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "きっとここのどこかに隠れてる！　くまなく探せ！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "He's got to be hiding here somewhere, that rat! Bring him to me!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "他一定就躲在這附近，給我仔細搜！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มันต้องซ่อนอยู่แถวนี้แหละไอ้หนูสกปรกนั่นน่ะ! ไปเอาตัวมันมาให้ได้!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Hẳn là nó trốn đâu đây, con chuột nhắt đó! Bắt nó đi!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "他一定就藏在这里的某个地方！给我仔细搜！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Er muss sich hier irgendwo verstecken, diese Ratte! Bringt ihn zu mir!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ce rat doit se cacher par ici, apportez-le-moi !"
L45_1.m_Talk_FRA = L46_1
