L51_1 = "이럴 때가 아니야. 어서 피해야 돼. 숨을 데가, 숨을 데가 있어야 하는데……."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "こうしてる場合じゃない。早く逃げないと。隠れる場所、隠れる場所が……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I-I need to get out of here. I need a place to hide... But wher–"
L50_1.m_Talk_ENG = L51_1
L51_1 = "不行，必須趕快找地方躲起來，要找地方躲起來……"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ตะ-ต้องหนีไปจากที่นี่ ต้องหาที่ซ่อนแล้ว... แต่ที่ไหนล–"
L50_1.m_Talk_THA = L51_1
L51_1 = "T-tôi cần ra khỏi đây. Tôi cần trốn... Nhưng ở đâu–"
L50_1.m_Talk_VTN = L51_1
L51_1 = "必须快点躲起来……快点躲起来。能藏的地方，必须找到一个能藏的地方……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich muss hier weg. Ich brauche einen Ort zum Verstecken ... Es muss doch einen Ort geben ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "J-Je dois sortir d'ici. Il faut que je me cache quelque part... mais où ?"
L50_1.m_Talk_FRA = L51_1
