L4_1 = "หรือเล่นซ่อนหากันคะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hay là trốn tìm?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "还是说摸瞎子？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Oder spielst du etwa „Verstecken“?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ou alors à cache-cache ?"
L3_1.m_Talk_FRA = L4_1
