L5_1 = "HAVEN_HAVEN_NULL_FAKE"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "구… 굳이 말하자면 술래잡기 쪽에 가깝긴 하지만……."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ま……まあ、鬼ごっこに近いかな……"
L4_1.m_Talk_JPN = L5_1
L5_1 = "W-well... More like tag, I think..."
L4_1.m_Talk_ENG = L5_1
L5_1 = "呃…硬要說的話，應該比較偏向鬼抓人吧……"
L4_1.m_Talk_TWN = L5_1
L5_1 = "กะ-ก็... ออกจะเหมือนซ่อนหามากกว่านะผมว่า..."
L4_1.m_Talk_THA = L5_1
L5_1 = "Ơ-ơ... chắc là giống trốn tìm hơn,..."
L4_1.m_Talk_VTN = L5_1
L5_1 = "非……非要说的话，更像是捉迷藏……"
L4_1.m_Talk_SCN = L5_1
L5_1 = "N-nun ja ... eher „Fangen“, denke ich ..."
L4_1.m_Talk_DEU = L5_1
