L7_1 = "ENEMY_HAVEN_NULL_C"
L6_1.m_CharStrID = L7_1
L7_1 = "저쪽이다! 말소리가 들렸어!!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あっちだ！　話し声が聞こえたぞ！！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Over there! I heard someone talking!!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "在那裡！有說話的聲音！！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ตรงนั้นไง! เสียงคนคุยกันอยู่!!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ở đằng kia! Có tiếng nói chuyện!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "在那边！我听到说话声了！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Da drüben! Ich habe jemanden reden hören!!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Là-bas ! J'entends quelqu'un parler !"
L6_1.m_Talk_FRA = L7_1
