L8_1.m_Face = "UNIT_DESPAIR"
L9_1 = "HAVEN_HAVEN_NULL_FAKE"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L8_1.m_Crash = 30
L9_1 = "뭐라고 생각하든 상관없으니까 제발 조용히 해! 이러다 들키겠어!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "何でもいいよ、頼むから静かにして！　このままじゃあバレる！"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Oh geez! Think of it what you will, but please be quiet! They're gonna catch me!"
L8_1.m_Talk_ENG = L9_1
L9_1 = "隨便叫什麼都好啦，拜託你安靜點！這樣我會被抓到啦！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "จะบ้าตาย! เอาที่สบายใจเลยนะเธอแต่ช่วยเงียบที! พวกนั้นมันจะจับผมได้อยู่แล้ว!"
L8_1.m_Talk_THA = L9_1
L9_1 = "Trời ơi! Sao cũng được, nhưng im lặng đi! Họ sẽ bắt được tôi mất!"
L8_1.m_Talk_VTN = L9_1
L9_1 = "不管你怎么想都好，拜托你别说话了！不然我该被发现了！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Es ist mir egal, was du denkst, aber sei bitte ruhig! Sie werden mich sonst schnappen!"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Bon sang ! Pense ce que tu veux, mais fais-le en silence ! Si ça continue, ils vont m'attraper !"
L8_1.m_Talk_FRA = L9_1
