L10_1 = "對吼，要躲起來才行！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อ๋อ งี้เอง! คุณต้องซ่อนสินะคะ!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ồ, phải rồi! Cậu phải trốn mà!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "噢噢！对呢！你得把自己藏起来！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ach ja, richtig! Du musst dich doch verstecken!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, c'est vrai. Tu dois resté cacher, hein ?"
L9_1.m_Talk_FRA = L10_1
