L39_1 = "บ้าเอ๊ย! ทำไมทางมันตันวะ?! หน้าที่ใครดูแลที่นี่เนี่ย?!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Chết tiệt! Sao đường lại bị chặn?! Ai quản lý nơi này thế?!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "该死，路被堵死了！这里是谁管理的！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Verdammt noch mal! Warum ist der Weg gesperrt?! Wer ist verantwortlich für die Verwaltung hier?!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Bon sang, on peut plus passer ! C'est quoi ce bordel ici, où est le responsable ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
