L40_1 = "왜 장비들이 멋대로 움직이는데! 당장 통제실에 연락해!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "なんで装備が勝手に動いてんだ！？　今すぐに制御室に連絡しろ！"
