L47_1 = "이 난리를 피우고 그냥 도망치게 둘 줄 알아! 다들 쫓아가!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "騒ぎを起こしておいて、逃げられるとでも思ってるのか！　追いかけろ！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You think we're gonna let you run away after causing all this mess?! GET HIM!!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "大鬧一場後就想閃人嗎！給我追！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "คิดว่าทำป่วนแบบนี้แล้วจะหนีไปได้เหรอ?! ไปจับตัวมันมา!!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Mày nghĩ mày sẽ thoát được sau khi gây ra đống lộn xộn này sao?! BẮT LẤY NÓ!!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "惹出这种乱子还想跑？！大家一起去追！"
L46_1.m_Talk_SCN = L47_1
