L3_1.m_Pos = "C"
L4_1 = "엣헴. 물론이지. 회사에서 술래잡기 할 때도 제일 늦게 잡혔는걸."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "えっへん。もちろんだよ。会社で鬼ごっこする時も一番最後まで捕まらないんだから。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Ahem! Of course! I'm the best at tag, even at work!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "嘿嘿，那還用說，每次在公司玩鬼抓人，我都是最後一個被抓到的。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮี่ฮี่! ได้สิคะ! ฉันเล่นซ่อนหาเก่งที่สุดเลยนะ ต่อให้ตอนทำงานก็เถอะ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hehe! Tất nhiên rồi! Tôi giỏi trò trốn tìm nhất, kể cả khi đi làm!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "哼哼~~那是当然。在公司玩捉迷藏的时候，我也是最后一个被抓到的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ähem! Natürlich! Immer wenn ich in unserem Unternehmen „Fangen“ gespielt habe, wurde ich als Letzte gefangen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Bien sûr, hé hé ! Au bureau aussi, je suis la meilleure à chat perché !"
