L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "고마워. 덕분에 살았어. 꼼짝없이 잡힐 줄 알았는데."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ありがとう。おかげで助かったよ。てっきり捕まると思ってたのに。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Thanks. You saved my life. I thought I was a goner..."
L4_1.m_Talk_ENG = L5_1
L5_1 = "得救了，謝謝你。我還以為只能束手就擒呢。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ขอบคุณนะ เธอช่วยผมไว้เลย นึกว่าจะม่องซะแล้ว..."
L4_1.m_Talk_THA = L5_1
L5_1 = "Cảm ơn. Cậu đã cứu tôi đấy. Tôi tưởng mình sắp đi đời rồi..."
L4_1.m_Talk_VTN = L5_1
L5_1 = "谢谢……我还以为只能等着被抓了呢……"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Danke. Du hast mir das Leben gerettet. Ich dachte schon, ich wäre erledigt ..."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Merci, tu m'as sauvé la vie. J'ai bien cru que j'allais y passer..."
L4_1.m_Talk_FRA = L5_1
