L9_1 = "응. 왜? 아빠랑 싸웠어?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "うん。どうしたの？　パパとケンカした？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Yes. Why? Did you have a fight with Daddy?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "嗯，怎麼了嗎？你和爸爸吵架喔？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อะเฮ้! ทำไมเหรอคะ? คุณทะเลาะกับคุณพ่อเหรอ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Uh-huh! Tại sao? Cậu đã cãi nhau với Bố sao?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "嗯。怎么了？你跟爸爸吵架了？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Hm? Was ist? Hast du etwa mit meinem Papa gestritten?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oui. Qu'est-ce qu'il y a ? Tu t'es battu avec lui ?"
