L9_1.m_Face = "UNIT_SURPRISE"
L10_1 = "HAVEN_HAVEN_NULL_FAKE"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "아, 아니. 그런 건 아니야. 화낸 것처럼 보였다면 미안……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "い、いや。そうじゃないよ。怒ってるように見えたならごめん……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "N-no. Nothing like that. I'm sorry if I seemed angry..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "沒有…不是的，我看起來像在生氣嗎？對不……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ปะ-เปล่า ไม่มีอะไรหรอก ขอโทษนะที่โกรธ..."
L9_1.m_Talk_THA = L10_1
L10_1 = "K-không. Làm gì có chuyện đó. Tôi xin lỗi nếu trông tôi có vẻ tức giận ..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "没、没有，不是那样的。如果我看起来像是在生气，那我很抱歉……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "N-nein, das ist es nicht. Es tut mir leid, wenn ich verärgert aussah ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "N-Non, c'est pas ça. Désolé si j'ai eu l'air énervé..."
L9_1.m_Talk_FRA = L10_1
