L11_1 = "히히, 괜찮아. 아저씨는 누구야?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "へへ、大丈夫。おじさんは誰？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Hehe. It's all right. But who're you, mister?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "嘻嘻，沒關係的，那叔叔你是誰？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ฮิฮิ ไม่เป็นไรค่า ว่าแต่คุณลุงเป็นใครเหรอคะ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Hehe. Không sao đâu. Nhưng anh là ai thế?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "嘻嘻，没关系。那么你是谁呀，叔叔？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Hihi. Ist schon gut. Aber wer bist du eigentlich, alter Mann?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Hi hi, c'est pas grave. Et toi m'sieur, t'es qui ?"
L10_1.m_Talk_FRA = L11_1
