L13_1 = "HAVEN_HAVEN_NULL_FAKE"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "그렇지. 네가 시그마라고 했으니까, 나는 루트로 할게. 누나 동생."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そうだね。君がシグマだからルートにする。僕は姉さんの弟だ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Okay. Since you said your name is Sigma, I'll go with Root. Sister's younger brother."
L12_1.m_Talk_ENG = L13_1
L13_1 = "有了，你叫西格瑪，那我就叫路特吧！姊姊的弟弟。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "โอเค ในเมื่อเธอบอกว่าชื่อซิกมา งั้นผมชื่อรูทแล้วกัน ผมมีพี่สาวน่ะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Được rồi. Vì cậu nói tên mình là Sigma, tôi sẽ lấy tên là Root. Em trai của chị gái."
L12_1.m_Talk_VTN = L13_1
L13_1 = "好吧，既然你说你叫西格玛，那我就叫根号好了，是姐姐的弟弟。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Okay. Da dein Name Sigma ist, kannst du mich Root nennen. Der jüngere Bruder meiner Schwester."
L12_1.m_Talk_DEU = L13_1
L13_1 = "D'accord, Sigma. Puisque tu m'as dit ton nom, voici le mien : Ruth. Je suis le frère de ma sœur."
L12_1.m_Talk_FRA = L13_1
