L17_1 = "NEVERLAND_ACT1_INTERLUDE1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4600102
L16_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_IDLE"
L16_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L16_1.m_Pos = "L"
L17_1 = "이건 내 비법인데 술래잡기는 술래를 무서워하면 안 돼. 그럼 금방 잡혀 버려."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "これは秘訣なんだけど、鬼ごっこは鬼を怖がっちゃダメだよ。すぐ捕まっちゃう。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I'll tell you my secret to being the best at tag. It's to not get scared. Or else, you’ll get caught in a heartbeat."
L16_1.m_Talk_ENG = L17_1
L17_1 = "告訴你我的絕招，玩鬼抓人的時候絕對不能怕鬼，否則很快就會被抓到的。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "จะบอกเคล็ดลับการเล่นซ่อนหาให้เก่งให้นะ คือต้องไม่กลัวไงล่ะ ไม่งั้นอึดใจเดียวก็โดนเจอแล้ว"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi sẽ cho cậu biết bí mật để trở thành người chơi trốn tìm giỏi nhất. Đó là không sợ hãi. Nếu không, cậu sẽ bị tóm nhanh thôi."
L16_1.m_Talk_VTN = L17_1
L17_1 = "这个可是我的秘诀，玩捉迷藏的时候不可以害怕。不然的话马上就会被捉到。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich werde dir meinen Geheimtipp verraten, wie man am besten „Fangen“ spielen kann. Du darfst keine Angst haben. Sonst kriegen sie dich sofort."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Puisqu'on est amis, je vais te dire mon secret pour être bon à chat perché. Il faut pas avoir peur ! Comme ça, tu te feras jamais attraper."
