L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "R"
L19_1 = "미안해. 사실 난 사람들을 엄청 무서워하거든."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ごめん。僕、実は人がとても怖いんだ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Sorry. To be honest with you, I'm really afraid of people..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "抱歉，不瞞你說，我超怕人的。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ขอโทษนะ แต่พูดตามตรงเลย ผมกลัวคนน่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Xin lỗi. Nói thật thì, tôi thực sự sợ mọi người ..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "对不起，其实我很怕人。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Tut mir leid. Um ehrlich zu sein, habe ich unheimlich viel Angst vor Menschen ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Désolé. Pour te dire la vérité, j'ai vraiment peur de ces gens..."
L18_1.m_Talk_FRA = L19_1
