L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L19_1.m_Crash = 10
L20_1 = "그래서 누나가 가면을 준 건데……."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "それで姉さんが仮面をくれたんだけど……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "That's why my sister gave me a mask, but..."
L19_1.m_Talk_ENG = L20_1
L20_1 = "所以姊姊才會給我面具……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เพราะแบบนั้นพี่สาวเลยให้หน้ากากมา แต่ว่า..."
L19_1.m_Talk_THA = L20_1
L20_1 = "Đó là lý do tại sao chị tôi đã đưa cho tôi một chiếc mặt nạ, nhưng..."
L19_1.m_Talk_VTN = L20_1
L20_1 = "所以姐姐才给了我一个面具……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Deshalb hat mir meine große Schwester eine Maske geschenkt, aber ..."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ma sœur m'avait donné un masque, mais..."
