L21_1 = "HAVEN_HAVEN_NULL_ROOT"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L20_1.m_Crash = 20
L21_1 = "맞아, 가면. 가면을 찾지 않으면 난… 난 또……."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そうだ、仮面。仮面を探さないと、僕……僕はまた……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Oh, right! My mask! If I don't find it, I'll... I'll–"
L20_1.m_Talk_ENG = L21_1
L21_1 = "對了，面具！要是不趕快找到面具…我又……"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อ้อ จริงสิ! หน้ากากผม! ถ้าหาไม่เจอละก็ ผมคง... ผมคง..."
L20_1.m_Talk_THA = L21_1
L21_1 = "Ô đúng rồi! Mặt nạ của tôi! Nếu tôi không tìm thấy nó, tôi sẽ... tôi sẽ...run rồi không làm gì được cả.."
L20_1.m_Talk_VTN = L21_1
L21_1 = "对了，面具！如果找不到面具，我……我又会……什么都做不了……"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ach ja! Meine Maske! Wenn ich sie nicht finde, werde ich ... Dann werde ich wieder ..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Oh, c'est vrai ! Mon masque ! Si je ne le trouve pas, je... je vais..."
L20_1.m_Talk_FRA = L21_1
