L21_1.m_Face = "UNIT_SURPRISE"
L21_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L21_1.m_Pos = "L"
L22_1 = "정말? 아까 같이 놀 때는 괜찮았잖아?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "本当？　さっき一緒に遊んでた時には大丈夫だったよ？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Really? But you were fine when we were playing together?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "真的嗎？可是我們剛剛一起玩的時候，你不是還好嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "จริงเหรอคะ? แต่ที่เราเล่นกันเมื่อกี้ก็ไม่เป็นไรนี่คะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Thật không? Nhưng cậu vẫn ổn khi chúng ta chơi với nhau mà?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "咦？可是刚才一起玩的时候你不是没事吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wirklich? Aber es ging dir doch gut, als wir zusammen gespielt haben, oder etwa nicht?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vraiment ? Mais tu allais bien tout à l'heure, non ?"
L21_1.m_Talk_FRA = L22_1
