L28_1[1] = L29_1
L28_1[2] = L30_1
L27_1.m_Bounce = L28_1
L28_1 = "응. 혼자 노는 것보다 함께 놀면 훨씬 즐겁거든."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "うん。一人で遊ぶより一緒に遊ぶ方がずっと楽しいもん。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Yes. It's always more fun when playing with others than by yourself!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "嗯！因為獨樂樂不如眾樂樂的嘛！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อาฮะ! เวลาเล่นกับคนอื่นก็สนุกกว่าเล่นคนเดียวทุกครั้งแหละค่ะ!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Uh-huh! Chơi với người khác lúc nào cũng vui hơn chơi một mình!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "嗯！因为比起一个人玩，几个人一起玩更有意思。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Genau! Es macht immer viel mehr Spaß, zusammen zu spielen, als alleine."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ben oui, hi hi. On s'amuse toujours plus à deux que quand on est tout seul !"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "NEVERLAND_ACT1_INTERLUDE1@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4600102
L28_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L28_1.m_Pos = "L"
L29_1 = "나도 루시드 언니네랑 놀다 보면 시간이 훌쩍 가 버려."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私もルシードお姉ちゃんたちと遊んでると、あっという間に時間が過ぎちゃう。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Like, time flies when I'm playing with Lucid and other kids!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "我和露西德姊姊她們一起玩的時候，也覺得時間過得特別快呢。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เหมือนแบบ พอเล่นกับลูซิดกับเพื่อนๆ แล้วเวลาผ่านไปเร็วมากเล้ย!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Giống như lúc tôi chơi với Lucid và cả nhóm, tôi thấy thời gian trôi nhanh lắm!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "我跟露西德还有别的姐姐一起玩的时候，也觉得时间过得很快。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Die Zeit vergeht immer wie im Flug, wenn ich mit Lucid und ihren Freunden spiele."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Moi aussi quand j'étais avec Lucid et les autres, je voyais pas le temps passer !"
L28_1.m_Talk_FRA = L29_1
