L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L30_1 = "맞아…… 나도 다른 사람들이랑 놀 때가 세상에서 제일 즐거워."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "そうだね……僕も一緒になって遊んでる時が世界で一番楽しいかな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Me too... I love playing with friends more than anything in the world, too."
L29_1.m_Talk_ENG = L30_1
L30_1 = "對欸……我也覺得和別人一起玩的時候是最開心的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ผมก็เหมือนกันนะ... ผมเองก็ชอบเล่นกับเพื่อนๆ ที่สุดเลยเหมือนกัน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi cũng vậy... Tôi cũng thích chơi với bạn bè hơn mọi thứ trên đời."
L29_1.m_Talk_VTN = L30_1
L30_1 = "没错……我也觉得跟别人一起玩是这世上最快乐的事。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Da hast du recht ... Ich liebe es auch, mehr als alles andere auf der Welt mit Freunden zu spielen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Tu as raison... Moi aussi c'est ce que je préfère, jouer avec mes amis."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
