L33_1 = "앗! 누, 누가 또 오나 봐! 어서 숨어야 돼!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あっ！　ま、また誰か来るみたいだ！　早く隠れないと！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Huh?! S-someone's coming! We gotta hide!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "唔！又有人來了！快躲起來！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "หือ?! มีคนกำลังมาทางนี้ล่ะ! ต้องซ่อนตัวแล้ว!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Huh?! A-ai đó đang đến! Chúng ta phải trốn mau!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "啊！好、好像又有人过来了！必须快点躲起来！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ah! Da kommt jemand! Wir müssen uns verstecken!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Oh ?! Quelqu'un arrive ! Vite, on doit se cacher !"
L32_1.m_Talk_FRA = L33_1
