L38_1 = "찾았다, 협력자."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "見つけた、協力者。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I found our cooperator."
L37_1.m_Talk_ENG = L38_1
L38_1 = "找到幫手了。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เจอผู้ร่วมปฏิบัติการของเราแล้ว"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi tìm thấy người cộng tác của chúng ta rồi."
