L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "맞아. 앞으로는 수아라고 불러 줘."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "そうだよ。これからはコトリって呼んで。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Right. Call me Skia from now on."
L39_1.m_Talk_ENG = L40_1
L40_1 = "沒錯，以後叫我蘇亞就好。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อ่าฮะ ต่อไปก็เรียกฉันว่าสเกียนะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Từ giờ hãy gọi tôi là Skia."
L39_1.m_Talk_VTN = L40_1
L40_1 = "没错，以后叫我秀鹅就好。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Korrekt. Nenn mich von nun an einfach Vroni."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oui. À partir de maintenant, tu peux m'appeler Néphie."
L39_1.m_Talk_FRA = L40_1
