L40_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "수아는 친구가 많구나! 다들 반가워!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "コトリは友達がたくさんいるんだね！　みんな、はじめまして！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You have a lot of friends, Skia! Hi everyone!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "蘇亞有好多朋友喔！大家好！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เพื่อนเธอเยอะจังสเกีย! ไงทุกคน!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cậu có nhiều bạn bè thế Skia! Chào mọi người!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "哇——！秀鹅的朋友真多啊！你们好呀！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Du hast aber viele Freunde, Vroni! Hallo alle zusammen!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ouah ! Tu as beaucoup d'amies, Néphie. Salut tout le monde !"
L40_1.m_Talk_FRA = L41_1
