L44_1 = "NEVERLAND_ACT1_INTERLUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4600102
L43_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_SURPRISE"
L44_1 = "NEWCOMER_NPC_DREAM_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "R_M_I"
L44_1 = "야, 그런 주먹구구식 암구호로 괜찮아? 정보가 새어 나갔으면 어쩌려고?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ちょっと、そんな大ざっぱな合言葉でいいの？　情報が漏れたらどうするんだよ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Hey, what kind of weak password was that? What if it got leaked?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "喂，用那麼簡單的暗號沒問題嗎？要是情報外洩的話怎麼辦？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "นี่ รหัสผ่านอะไรมันจะง่อยขนาดนั้น? เกิดรั่วออกไปล่ะ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Này, mật khẩu gì mà yếu vậy? Nếu nó bị leak thì sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "喂，用这种稀松平常的暗号也没关系吗？信息泄露了怎么办？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Hey, was für ein schwaches Passwort war das denn? Was ist, wenn es durchgesickert ist?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Hé, c'est quoi ce mot de passe bidon ? Et si il avait fuité ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NEVERLAND_ACT1_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4600102
L44_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "UNIT_HATE"
L44_1.m_Face = L45_1
L45_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "L"
L45_1 = "확실해. 서로 고유 번호를 공유했으니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "確かだよ。お互いのシリアルナンバーを共有したから。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I'm certain it's her. We even shared our unique ID numbers."
L44_1.m_Talk_ENG = L45_1
L45_1 = "沒問題的，我們有先給對方彼此的編號。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ต้องใช่เธอแน่ เราใช้เลขประจำตัวเดียวกันด้วยซ้ำ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi chắc chắn đó là cô ấy. Chúng tôi còn chia sẻ số ID riêng cho nhau nữa."
L44_1.m_Talk_VTN = L45_1
L45_1 = "没问题。我们互相共享了，固有编号。"
L44_1.m_Talk_SCN = L45_1
