L8_1 = "차림새며 머리며 딱 봐도 헤이븐 형님 극성팬이네."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "服から髪型まで、どう見てもヘイブン兄貴の熱狂的なファンでしょ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Just looking at how you dress and do your hair, you must be a real fan."
L7_1.m_Talk_ENG = L8_1
L8_1 = "看你的穿著打扮和髮型，就知道你是天堂大哥鐵粉！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ดูเสื้อผ้าหน้าผมแล้วติ่งชัดๆ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Xem cách cậu ăn mặc và làm tóc, cậu hẳn là fan hâm mộ thực sự."
L7_1.m_Talk_VTN = L8_1
L8_1 = "你的穿着打扮、还有发型，一看就是海文老大的铁杆粉丝。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wenn ich mir nur dein Outfit und deine Haare so ansehe, scheinst du ein großer Fan von Boss Haven zu sein."
L7_1.m_Talk_DEU = L8_1
L8_1 = "À voir ta tenue et ta coiffure, c'est facile de deviner."
