L9_1 = "NEVERLAND_ACT1_INTERLUDE1@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4600102
L8_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_IDLE"
L9_1 = "NEWCOMER_NPC_DREAM_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "하지만 결국 겉모습뿐이야. 형님 흉내를 내려면 먼저 그 얼빠진 태도부터 고쳐야지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "でも結局外見だけ。兄貴のマネをするなら、まずその間の抜けた態度から直しなよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "You're spot on with the costume and all, but you gotta fix that stupid attitude if you want to act like him too."
L8_1.m_Talk_ENG = L9_1
L9_1 = "不過也只有外表像啦，要想模仿大哥的話，起碼先把那副畏畏縮縮的態度改掉吧！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เสื้อผ้ามันก็ได้หรอกนะ แต่ถ้าอยากทำตัวเหมือนเขาจริงก็ต้องเปลี่ยนแอตติจูดหน่อย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Anh bắt chước trang phục và mọi thứ, nhưng anh phải sửa thái độ đó nếu muốn ra vẻ như ông ta."
L8_1.m_Talk_VTN = L9_1
L9_1 = "不过说到底你也只是外表像。要想模仿老大，你必须先改掉这副呆样。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Mit dem Kostüm und allem bist du zwar auf dem richtigen Weg, aber du musst deine Haltung ändern, wenn du ihn wirklich nachahmen willst."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Chapeau pour le cosplay, mais si tu veux vraiment lui ressembler... il va falloir que tu travailles un peu l'allure."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NEVERLAND_ACT1_INTERLUDE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
