L10_1 = "HAVEN_HAVEN_NULL_ROOT"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "아니, 저, 있지, 그게……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "いや、その、あのさ、それが……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Wait... Um... Well, the thing is..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "不是的，那個，我，就是……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เดี๋ยวนะ... เอ่อ... เรื่องของเรื่องคือ..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Đợi đã... Ừm... Chà, chuyện là..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "不是，我，那个，就是……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ähm, nun ja, das Ding ist ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Ah euh, en fait je..."
L9_1.m_Talk_FRA = L10_1
