L11_1 = "NEVERLAND_ACT1_INTERLUDE1@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4600102
L10_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SERIOUS"
L11_1 = "NEWCOMER_NPC_DREAM_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "어차피 형님 따라할 거면 좀 비슷하기라도 해야되지 않겠어?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "どうせ兄貴のマネをするなら似せないとね？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I mean, if you're gonna do it, you might as well go all-out, right?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "既然要模仿，就要模仿得像一點吧？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "คือ จะทำทั้งที่ก็ให้มันเต็มที่หน่อย จริงมั้ย?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Ý tôi là, nếu muốn làm điều đó, cũng phải làm cho tới phải không?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "总之想模仿老大的话，好歹应该装得像点啊？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wenn du ihn schon nachahmen willst, dann solltest du wirklich darauf achten, ihn bis aufs kleinste Detail zu imitieren."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Si tu es parti pour l'imiter, il faut faire les choses jusqu'au bout !"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NEVERLAND_ACT1_INTERLUDE1@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4600102
L11_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "NEWCOMER_NPC_DREAM_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L11_1.m_Crash = 30
L12_1 = "자, 어깨도 활짝 펴고! 눈에도 힘 빡! 주고!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ほら、胸張って！　目にもグッと力入れて！！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Now, straighten your back! Put some life into those eyes, all right?!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "來，抬頭挺胸！眼睛要炯炯有神！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เอ้า อกผายไหล่ผึ่ง! ทำตาให้มันมีชีวิตชีวาหน่อย โอเค้?!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nào, thẳng lưng lên! Thần thái lên đi chứ?!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "来，抬头挺胸！眼神也犀利点！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Schultern zurück und gerade stehem! Lass deine Augen strahlen! Na los!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Là, commence par te redresser ! Lève la nuque, allume la flamme dans tes yeux !"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "NEVERLAND_ACT1_INTERLUDE1@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4600102
L12_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "UNIT_PRIDE"
L12_1.m_Face = L13_1
L13_1 = "NEWCOMER_NPC_DREAM_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "너 따위는 아무것도 아니라는 듯이 입꼬리 살짝 올려주고!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "お前なんかはなんでもないって風に口角ちょっぴり上げて！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Then grin like you're better than everyone else!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "嘴角微微上揚，一副不可一世的樣子！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ทีนี้ก็ฉีกยิ้มให้เหมือนตัวเองเลิศกว่าทุกคนซะ!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nào, cười toe như thể cậu vui hơn bất kỳ ai khác!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "嘴角稍微上扬，摆出一副你这种渣渣什么都不是的睥睨姿态！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Dann grinse so, als wärst du besser als alle anderen!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Et maintenant, souris comme si tu étais le roi du monde !"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NEVERLAND_ACT1_INTERLUDE1@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4600102
L13_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "NEWCOMER_NPC_DREAM_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "형님을 노리는 암살자들을 차갑게 내리 깔아 보면서 손짓 한 방으로 날려 버리고!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "兄貴を狙う暗殺者どもを冷たく見下ろしながら、敵を手一振りで吹っ飛ばし！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Stare down with a bone-chilling stare as you raise your finger to get rid of those assassins after you!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "冷眼俾倪想要暗殺大哥的殺手，一個手勢就打趴殺手！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "มองเหยียดแบบให้เสียวสันหลังด้วย เวลายกนิ้วกำจัดพวกมือลอบสังหารที่ไล่ตามมาน่ะ!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Hãy nhìn xuống thật lạnh lùng khi anh giơ ngón tay lên để thoát khỏi những tên sát thủ đang đuổi theo!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "冷冷地俯视觊觎老大地位的暗杀者们，一个招式就把他们全都打飞！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Starr so kaltblütig wie nur möglich, während du diese Attentäter, die hinter dir her sind, mit einem Fingerschnipsen los wirst!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Abaisse le pouce comme dans les films pour te débarrasser des types qui veulent ta peau !"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
