L15_1 = {}
L16_1 = 2
L17_1 = 0.15
L15_1[1] = L16_1
L15_1[2] = L17_1
L14_1.m_Bounce = L15_1
L15_1 = "언제나 새로운 재밋거리를 찾아서 고고한 학처럼 사뿐사뿐 걸어가다가……."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "いつも新しい遊びを探すように、まるで孤高な鶴のごとく静かに歩いて行き……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "And walk like a majestic crane searching for fun as you..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "總是在尋找新的樂趣，像隻孤傲的鶴一般踏著輕盈的步伐……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แล้วก็เดินให้มันเหมือนนกกระเรียนสวยๆ ที่กำลังหาเรื่องสนุกๆ ในตอนที่..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Và bước đi hùng dũng như một con sếu hùng vĩ đang tìm kiếm niềm vui khi cậu..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "像是孤傲的鹤一样迈着轻盈的步伐，寻找新的乐趣……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "So leichtfüßig wie ein Kranich, der immer auf der Suche nach etwas Neuem ist, das ihm Spaß macht ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Marche avec autorité et détermination, toujours à la recherche d'un nouveau plaisir..."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
