L16_1[2] = L18_1
L15_1.m_Bounce = L16_1
L16_1 = "이미 뻗어 버린 암살자의 손목을 사뿐히 즈려 밟으면서 치명적인 웃음 한 방! 캬아!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "すでにのびている暗殺者の手首を軽く踏みにじりながら、トドメの笑みを浮かべるの！　きゃあ！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "step on the fallen assassin's wrist and let out a charming laugh! *Squeal*"
L15_1.m_Talk_ENG = L16_1
L16_1 = "接著輕踩在倒在地上的殺手手腕上，露出致命的微笑！超帥！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เหยียบข้อมือมือลอบสังหารพวกนั้น แล้วก็หัวเราะแบบมีบารมีออกมา! *เสียงแหลม*!"
L15_1.m_Talk_THA = L16_1
L16_1 = "giẫm lên cổ tay của tên sát thủ đã ngã xuống và cất tiếng cười ma mị! *Cười ré lên*"
L15_1.m_Talk_VTN = L16_1
L16_1 = "踩在已经没有了声息的暗杀者的手腕上，并予以致命一笑！咔啊——！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Tritt auf das Handgelenk der zu Boden gefallenen Attentäter und lach so charmant wie es nur geht! *Gelächter*"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Et piétine les mains des ennemis tombés à tes pieds, en laissant échapper un rictus démoniaque !"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
