L17_1 = "RUNNER_OZ_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "그거 대체 누구 얘기야?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "それ、いったい誰のこと？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Just who are you even talking about?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "你現在是在說誰？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "นี่เธอพูดถึงใครก่อน?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cô đang nói cái quái gì thế?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "你究竟是在说谁啊？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Von wem redest du überhaupt?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "De qui tu parles, là ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NEVERLAND_ACT1_INTERLUDE1@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4600102
L17_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_PRIDE"
L17_1.m_Face = L18_1
L18_1 = "NEWCOMER_NPC_DREAM_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "넌 위저드에 있었으면서 그것도 몰라? 당연히 우리 헤이븐 형님 얘기지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ウィザードにいたくせにそんなのも知らないの？　もちろん我らがヘイブン兄貴のことだよ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "You seriously don't know? It's Mr. Haven! You were at Wizard so you should know."
L17_1.m_Talk_ENG = L18_1
L18_1 = "你在巫師裡這麼久竟然不知道？當然是在說我們天堂大哥！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ไม่รู้จริงเหรอ? ลูกพี่แฮฟเวนไง! เธออยู่ที่วิซาร์ดก็ต้องรู้สิ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô thực sự không biết à? Đó là Sếp Haven! Cô đã từng ở Wizard nên cậu hẳn phải biết."
L17_1.m_Talk_VTN = L18_1
L18_1 = "亏你还在巫师会待过呢，连这个都不知道吗？说的当然是海文老大了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Du warst doch bei Wizard, also wie kannst du nicht einmal das wissen? Natürlich rede ich von unserem Boss Haven."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Quoi, vous savez vraiment pas ? Haven, bien sûr ! Vous êtes du Wizard pourtant, vous devriez savoir..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NEVERLAND_ACT1_INTERLUDE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
