L20_1 = "NEVERLAND_ACT1_INTERLUDE1@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4600102
L19_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "CUTSCENE_TALK_06"
L19_1.m_StartBGMFileName = L20_1
L20_1 = "RUNNER_OZ_NULL_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "그 잘난 형님이 우리에게 무슨 짓을 했는지는 기억하냐? 잊어 먹은 모양인데?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そのカッコいい兄貴とやらが何をしたのか覚えてる？　忘れてるみたいだけど。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Do you remember what that \"amazing boss\" did to us? Or did you already forget?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你還記得那位了不起的大哥對我們做了什麼嗎？我看你好像全忘光咧？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ยังอยู่ในหัวมั้ยนะว่า \"ลูกพี่สุดเท่\" นั่นทำอะไรเราไว้บ้าง? ลืมแล้วรึไง?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cô có nhớ \"ông chủ tuyệt vời\" đó đã làm gì với chúng ta không? Hay cô đã quên hết rồi?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "你还记得你口中那个了不起的老大对我们做了什么吗？我看你好像都忘了？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Erinnerst du dich noch, was uns der „großartige“ Boss Haven angetan hat? Du scheinst es vergessen zu haben ..."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Tu as déjà oublié ce que ce sale type nous a fait ? Tu as la mémoire courte, on dirait."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NEVERLAND_ACT1_INTERLUDE1@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4600102
L20_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_DESPAIR"
L21_1 = "NEWCOMER_NPC_DREAM_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "……아니. 헤론이면 모를까, 형님에 대해선 뭔가 오해가 있는 게 틀림없어."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "……いや。ヘロンならともかく、兄貴については何が誤解があるに違いないよ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I mean... Heron, yeah. But I'm certain there's some sort of misunderstanding about Mr. Haven."
L20_1.m_Talk_ENG = L21_1
L21_1 = "……我沒忘，先姑且不說海倫，但大哥的部分肯定是哪裡有誤會啦！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "คือ... เฮรอนน่ะใช่ แต่ฉันว่ากับลูกพี่แฮฟเวนน่ะต้องมีอะไรเข้าใจผิดแน่"
L20_1.m_Talk_THA = L21_1
L21_1 = "Ý tôi là... Heron, yeah. Nhưng tôi chắc chắn rằng có một số hiểu lầm về Sếp Haven."
L20_1.m_Talk_VTN = L21_1
L21_1 = "……不，说是海伦做的还有可能，你肯定对老大有什么误会。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wenn du Heron meinst, dann ja. Aber ich bin mir sicher, dass es sich um ein Missverständnis bezüglich Boss Haven handelt."
L20_1.m_Talk_DEU = L21_1
L21_1 = "... Pour Madame Heron c'est indiscutable, mais je pense que M. Haven est victime d'un terrible malentendu..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "NEVERLAND_ACT1_INTERLUDE1@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4600102
L21_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L22_1 = "NEWCOMER_NPC_DREAM_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "잔악무도하고 무시무시하단 소리는 많이 들었어도, 비겁한 사람이란 얘기는 없었다고."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "残虐非道で恐ろしいって話はよく聞いても、卑怯な人だって話は聞いたことないからさ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You might've heard he's ruthless and violent, but you'll never hear anyone say that he's despicable."
L21_1.m_Talk_ENG = L22_1
L22_1 = "常有人說他冷血兇殘，但從來沒人說過他是懦夫。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เราอาจได้ยินกันมาว่าเขาโหดร้ายใจอำมหิต แต่ไม่เคยมีใครบอกว่าเขาขี้ขลาดนะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nghe nói rằng người đó tàn bạo và độc ác, nhưng mọi người  sẽ không bao giờ biết có người nói rằng ông ta còn hèn nhát nữa."
L21_1.m_Talk_VTN = L22_1
L22_1 = "虽然经常听别人说老大残忍、可怕，但还从来没听谁说过他卑鄙。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich habe viele Leute sagen hören, dass er grausam und furchterregend sei, aber niemand hat gesagt, dass er ein Feigling sei."
L21_1.m_Talk_DEU = L22_1
L22_1 = "On a beau dire qu'il est cruel et impitoyable... personne ne l'a jamais traité de lâche."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NEVERLAND_ACT1_INTERLUDE1@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4600102
L22_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_HATE"
L22_1.m_Face = L23_1
L23_1 = "RUNNER_OZ_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "글쎄? 헤론도 헤이븐 부하 아냐?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "どうかな。ヘロンもヘイブンの部下だろ？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Well, isn't Heron one of Haven's underlings?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "是嗎？海倫不是天堂的手下嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "จริงเหรอ? แต่เฮรอนนี่ก็ลูกกระจ๊อกแฮฟเวนเหมือนกันรึเปล่านะ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Thật không? Nhưng chẳng phải Heron là thuộc hạ của Haven sao?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "这可难说，海伦不是海文的部下吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wirklich? Aber ist Heron nicht eine von Havens Untergebenen?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Tiens donc. Heron est pourtant sur les ordres de Haven, non ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NEVERLAND_ACT1_INTERLUDE1@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4600102
L23_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "RUNNER_OZ_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "그럼 보나마나 그 마녀 할멈이랑 쿵짝 잘 맞는 타입이겠지, 뭘."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "あの魔女ババアと息のピッタリ合うタイプに違いないよ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That just shows that he's the type that gets along well with that hag."
L23_1.m_Talk_ENG = L24_1
L24_1 = "那想也知道他和那老巫婆是同一種人吧！嘖！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ซึ่งมันก็แปลว่าเขาเป็นพวกที่เข้ากับยัยแก่นั่นได้ไง"
L23_1.m_Talk_THA = L24_1
L24_1 = "Điều đó chỉ chứng tỏ rằng ông ta là kiểu người hợp với mụ ta thôi."
L23_1.m_Talk_VTN = L24_1
L24_1 = "那么显而易见地，他跟那个魔女老太婆应该很合拍吧。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Es zeigt nur, dass er die Art von Mensch ist, die gut mit einer Hexe wie ihr auskommt."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Ça montre juste qu'il arrive à s'entendre avec cette sorcière, malgré son caractère."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
