L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4600102
L25_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L26_1 = "SWORD_OZ_NULL_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "C_M_I"
L25_1.m_Pos = L26_1
L26_1 = "저기, 수아야. 협력자가 두 명이었어? 미리 얘기라도 해주지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "コトリちゃん。協力者って二人だったの？　ちゃんと話してほしかったなあ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Um, Skia? There were two cooperators? You should've said so beforehand..."
L25_1.m_Talk_ENG = L26_1
L26_1 = "蘇亞，幫手有二位嗎？怎麼沒先跟我們說？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "อืม สเกีย? มีผู้ร่วมปฏิบัติการสองคนเหรอ? เธอน่าจะบอกกันก่อนนะ..."
L25_1.m_Talk_THA = L26_1
L26_1 = "Um, Skia? Có hai người cộng tác cơ à? Lẽ ra cậu nên nói trước..."
L25_1.m_Talk_VTN = L26_1
L26_1 = "秀、秀鹅。所以有两个线人吗？你怎么没提前说一声……"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ähm, Vroni? Es gab zwei Verbündete? Das hättest du vorher sagen sollen ..."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Euh, Néphie ? Il y avait deux collaborateurs en fait ? Tu aurais dû nous le dire."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "NEVERLAND_ACT1_INTERLUDE1@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4600102
L26_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
