L27_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "아니. 협력자는 한 명이야."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "いや。協力者は一人だよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "No. There is only supposed to be one."
L26_1.m_Talk_ENG = L27_1
L27_1 = "不，幫手只有一位。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไม่นะ ควรจะมีแค่คนเดียวต่างหาก"
L26_1.m_Talk_THA = L27_1
L27_1 = "Không. Chỉ có một thôi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "不，只有一个线人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Nein, eigentlich soll es nur eine geben."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Non, un seul."
L26_1.m_Talk_FRA = L27_1
