L29_1 = "UNIT_HATE"
L28_1.m_Face = L29_1
L29_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "누구야, 넌. 대답 안 하면 후추탄을 쏘겠어."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "アナタは誰？　答えないとコショウ弾を撃つ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Who are you? Answer, or I'll shoot you with pepper bullets."
L28_1.m_Talk_ENG = L29_1
L29_1 = "你到底是誰？再不說的話，我就向你發射胡椒彈。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "คุณเป็นใครน่ะ? ตอบมานะ ไม่งั้นจะเอากระสุนพริกไทยยิงนะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cậu là ai? Trả lời ngay nếu không thì ăn đạn cay."
L28_1.m_Talk_VTN = L29_1
L29_1 = "你是谁。不回答的话，就用胡椒弹射你了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wer bist du dann? Antworte, oder ich werde dich mit Pfefferspray beschießen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Qui es-tu ? Réponds, ou je te fais goûter mes balles au poivre."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
