L29_1.m_Crash = 20
L30_1 = "쏘, 쏘지 마! 나는 그저……."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "う、撃たないで！　僕はただ……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "P-please don't shoot! I'm..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "不…不要！我是……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ยะ-อย่ายิงนะ! ขอร้องล่ะ ผมคือ..."
L29_1.m_Talk_THA = L30_1
L30_1 = "L-làm ơn đừng bắn! Tôi..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "别、别开枪！我就是……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "B-bitte nicht schießen! Ich bin ..."
L29_1.m_Talk_DEU = L30_1
L30_1 = "N-Non, ne tirez pas ! Je suis juste..."
L29_1.m_Talk_FRA = L30_1
