L33_1 = "NEVERLAND_ACT1_INTERLUDE1@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4600102
L32_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_SERIOUS"
L33_1 = "SWORD_OZ_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "대답하지 않으면 큰일날 거야. 수아는 피도 눈물도 없는 냉혈한이거든."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "答えないと大変なことになるよ。コトリちゃんは血も涙もない冷血漢だから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You'd better answer fast. Skia’s as heartless as they come."
L32_1.m_Talk_ENG = L33_1
L33_1 = "你再不說的話就要倒大楣囉，蘇亞可是沒血沒淚的冷血動物。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "รีบตอบจะดีกว่านะคะ เพราะสเกียน่ะไร้หัวใจแบบไม่มีสักนิดเลยค่ะ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Anh nên nhanh mồm nhanh miệng lên. Skia cũng nhẫn tâm lắm."
L32_1.m_Talk_VTN = L33_1
L33_1 = "答不上来的话，你就死定了！秀鹅可是个无血无泪的冷血动物~~"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wenn du nicht antwortest, bekommst du Schwierigkeiten. Vroni ist nämlich eiskalt und schießt, ohne auch nur mit der Wimper zu zucken."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tu ferais mieux de répondre. Néphie a un vrai cœur de pierre."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NEVERLAND_ACT1_INTERLUDE1@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4600102
L33_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_HATE"
L33_1.m_Face = L34_1
L34_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "그 정도까지는 아니야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それほどではない。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I wouldn't go that far."
L33_1.m_Talk_ENG = L34_1
L34_1 = "是沒到那種程度。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ก็ไม่ขนาดนั้นหรอก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi không tới nỗi thế đâu."
L33_1.m_Talk_VTN = L34_1
L34_1 = "没你说的，那么夸张。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "So weit würde ich nun auch wieder nicht gehen …"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je n'irai pas jusque là."
L33_1.m_Talk_FRA = L34_1
