L37_1 = "NEVERLAND_ACT1_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4600102
L36_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_IDLE"
L36_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "여기서 새로 사귄 친구야. 방금까지 같이 술래잡기 하고 있었어."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "この人はここで新しくできた友達なの。さっきまで一緒に鬼ごっこしてたんだ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "He's a new friend I made here. We were playing tag."
L36_1.m_Talk_ENG = L37_1
L37_1 = "他是我在這裡交的新朋友，我們剛有一起玩鬼抓人。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เขาเป็นเพื่อนใหม่นะ เราเพิ่งเป็นเพื่อนกันเนี่ย เมื่อกี้เราเล่นซ่อนหากัน"
L36_1.m_Talk_THA = L37_1
L37_1 = "Anh ấy là người bạn mới mà tôi đã làm quen ở đây. Chúng tôi đang chơi trốn tìm đáy."
L36_1.m_Talk_VTN = L37_1
L37_1 = "他是我在这里新交的朋友。刚才我们一起玩捉迷藏了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Er ist ein neuer Freund, den ich hier kennengelernt habe. Wir haben zusammen „Fangen“ gespielt."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est un nouvel ami que je me suis fait en arrivant ici. On jouait à chat perché."
L36_1.m_Talk_FRA = L37_1
