L40_1 = "NEVERLAND_ACT1_INTERLUDE1@189#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 189
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4600102
L39_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_IDLE"
L40_1 = "RUNNER_OZ_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "그럼 얼른 쫓아내야지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "じゃあ、早く追い出そう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Then tell him to go away now."
L39_1.m_Talk_ENG = L40_1
L40_1 = "那快把他趕走吧。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "งั้นก็บอกให้เขาไสหัวไปเลยไป"
L39_1.m_Talk_THA = L40_1
L40_1 = "Vậy bảo anh ta đi đi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "那就赶紧赶他走。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Dann sag ihm, er soll sich jetzt ganz schnell verziehen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Eh bien maintenant, il peut partir."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "NEVERLAND_ACT1_INTERLUDE1@190#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4600102
L40_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "RUNNER_OZ_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "L"
L41_1 = "엔진실로 가서 함선을 불시착시킬 거잖아. 우리랑 같이 다니면 괜히 위험해질걸."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "エンジンルームに行って艦船を不時着させるんだろ？　私たちと一緒にいると危険だよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "We need to head to the engine room and crash-land this ship. It'll be dangerous for him to keep following us around."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我們要去引擎室讓艦船迫降欸，他跟我們一起行動反而會有危險吧？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เราต้องไปที่ห้องเครื่องยนต์แล้วทำให้ยานนี่ตกนะ เขามาตามต้อยๆ แบบนี้จะอันตรายกับตัวเองซะเปล่า"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chúng ta cần đến phòng máy và hạ cánh con tàu này. Anh ta cứ lẽo đẽo theo chúng ta thì quá nguy hiểm."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我们不是要去发动机舱，想办法让舰船迫降吗？如果跟我们一起去，他也会有危险的。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wir müssen in den Maschinenraum gehen und das Schiff abstürzen lassen. Es wird zu gefährlich für ihn sein, uns weiterhin zu folgen."
L40_1.m_Talk_DEU = L41_1
L41_1 = "On va dans la salle des machines pour provoquer un accident, là. Ça va être dangereux pour lui s'il vient avec nous."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NEVERLAND_ACT1_INTERLUDE1@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4600102
L41_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_DESPAIR"
L42_1 = "SWORD_OZ_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "R"
L42_1 = "이젠 우리 작전까지 알아버렸어……. 그냥 보내줬다가 우리 얘기를 떠들기라도 하면 어떡해?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "もう作戦まで知られちゃった……このまま帰して、私たちの話でもしたらどうするの？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Great. Now he even knows about our mission... Now we can't afford to let him go. He might tell someone about us!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "他已經知道我們的計畫咧……就這樣放他走的話，萬一他把我們的計畫告訴別人怎麼辦？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แจ๋วเลยค่ะ ตอนนี้เขารู้กระทั่งภารกิจเราแล้ว... เราคงปล่อยเขาไปไม่ได้แล้วนะคะ เดี๋ยวเอาเรื่องเราไปบอกใครพอดี!"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tuyệt vời. Bây giờ anh ta còn biết chúng ta đến đây làm gì nữa cơ... Bây giờ chúng ta không thể để anh ta đi bép xép với người khác nữa!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "多……多萝西！你把作战计划都告诉他了……就这么放他走了，他把我们的事说出去怎么办？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Na ganz toll! Jetzt weiß er sogar über unsere Mission Bescheid ... Jetzt können wir ihn nicht mehr so einfach gehen lassen. Er könnte jemandem von uns erzählen!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Super. Maintenant, il connaît même notre mission ... Et s'il allait parler à quelqu'un ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NEVERLAND_ACT1_INTERLUDE1@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4600102
L42_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_HATE"
L42_1.m_Face = L43_1
L43_1 = "RUNNER_OZ_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "L"
L43_1 = "으음. 그러게. 어떡하지?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "うーん。そうだな。どうしようか？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Hmm. Right... Now what do we do?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "嗯嗯，你說的也對，那要怎麼辦？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อืม ก็จริงแฮะ... งั้นเอาไงกันดีเรา?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Hmm. Đúng vậy... Bây giờ chúng ta phải làm gì?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "呃嗯。就是啊。怎么办呢……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hmm. Du hast recht. Was machen wir denn jetzt?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh, c'est pas faux. Qu'est-ce qu'on fait de lui, alors ?"
L42_1.m_Talk_FRA = L43_1
