L45_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "뒷목을 쳐서 기절시키자."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "首トンで気絶させよう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Let's knock him out by hitting him behind the head."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不如就打他後腦勺弄暈他吧。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ฟาดท้ายทอยเขาให้สลบกัน"
L44_1.m_Talk_THA = L45_1
L45_1 = "Hãy hạ gục anh ta đi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "干脆打晕了吧。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Hauen wir ihm eine runter, damit er bewusstlos wird!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Un coup sur la tête pour l'endormir."
L44_1.m_Talk_FRA = L45_1
