L49_1 = "NEVERLAND_ACT1_INTERLUDE1@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 4600102
L48_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_SERIOUS"
L49_1 = "NEWCOMER_NPC_DREAM_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L48_1.m_Crash = 20
L49_1 = "야! 애초에 작전을 떠벌린 건 너네들이잖아?!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ちょっと！　だいたい作戦をべらべら喋ったのはアンタたちでしょ！！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Hey! You're the ones who just told him everything!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "喂！是你們自己大嘴巴透露計畫的欸？！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นี่! ไอ้ที่บอกเขาหมดน่ะมันเธอมั้ยนะ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Này! Cô chính là người vừa nói với anh ta mọi thứ!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "喂！作战计划是你们自己泄露的吧？！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Hey! Du bist diejenige, die ihm gerade alles erzählt hat!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Hé ! C'est toi qui lui a parlé de notre plan je te signale !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NEVERLAND_ACT1_INTERLUDE1@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4600102
L49_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_IDLE"
L50_1 = "NEWCOMER_NPC_DREAM_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "흥분한 건 알겠는데 진정 좀 해라. 그 솜털 같은 주먹으로 쳐 봤자 기절도 안 할 거야."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "興奮するのはわかるけど、ちょっとは落ち着いてよ。その綿みたいな拳で叩いても気絶しないだろうしさ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I know you're anxious, but calm down a bit, okay? Plus, no one's gonna faint if you punch them with those tiny fists of yours."
L49_1.m_Talk_ENG = L50_1
L50_1 = "你們先冷靜下來，別那麼激動。況且你的拳頭輕得跟羽毛一樣，就算打下去也不會暈好嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "รู้นะว่ากังวลกัน แต่ใจเย็นลงนิดได้มั้ย? แถมกำปั้นตะมุตะมิแบบนั้นมันต่อยใครสลบไม่ได้หรอก"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi biết cô đang lo lắng, nhưng bình tĩnh một chút đi, được chứ? Với lại, cú đấm nhỏ xíu đó cũng chẳng làm ai ngất nổi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "还有拜托你们冷静点啊——就你们那软绵绵的拳头，打在他身上，他也不会晕倒。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich weiß ja, dass du Angst hast, aber beruhige dich ein bisschen, okay? Außerdem wird niemand ohnmächtig, wenn du ihn mit deinen winzigen Fäustchen schlägst."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je comprends que vous soyez un peu sur les nerfs mais calmez-vous, ok ? Et puis c'est pas avec ton poing que tu vas le mettre K.O. de toute façon."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
