L7_1.m_fTalkTime = 0.03
L8_1 = "やめなさいよ。あれじゃすぐぶっ倒れちゃう。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Stop it! You're freaking him out."
L7_1.m_Talk_ENG = L8_1
L8_1 = "好了啦，再這樣他真的會嚇到暈過去。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "หยุดเดี๋ยวนี้นะ! พวกเธอทำเขากลัวแย่แล้ว..."
L7_1.m_Talk_THA = L8_1
