L9_1 = "……わかった。確かに危険な人ではなさそうだね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "...Okay. He really doesn't seem like a dangerous person."
L8_1.m_Talk_ENG = L9_1
L9_1 = "……好吧，他看起來確實不像危險人物。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "โอเค เขาดูไม่ใช่คนอันตรายจริงๆ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Được rồi. Anh ta có vẻ chẳng có gì nguy hiểm."
L8_1.m_Talk_VTN = L9_1
L9_1 = "……好吧。他看起来，确实不像危险人物。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Na gut. Er scheint wirklich nicht gefährlich zu sein."
