L9_1.m_Pos = "C"
L10_1 = "그렇다고는 해도 혹을 달고 다닐 수는 없어. 짐짝은 글린다 하나로 충분해."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "だとしても邪魔者と一緒に歩き回るのはなしだよ。お荷物はグリンダ一人で十分。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "But we can't drag along yet another person. We're already full as it is with Glinda."
L9_1.m_Talk_ENG = L10_1
L10_1 = "話雖如此，我們總不能帶著一個拖油瓶行動吧？難道有格琳達這一個拖油瓶還不夠嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แต่เราจะเที่ยวลากคนอื่นไปด้วยอีกไม่ได้นะ แค่กลินดาก็เต็มคาราเบ้วแล้ว"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nhưng chúng ta không thể kéo theo thêm một người nào nữa. Mỗi Glinda thôi đã quá đủ rồi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "不过即便如此，我们也不能带个累赘。累赘有格琳达一个就够了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Aber wir können nicht noch eine weitere Person mitschleppen. Mit Glinda sind wir schon vollkommen ausgelastet."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Mais si on le prend avec nous, il va juste nous gêner. On est déjà assez chargées comme ça avec Glinda."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NEVERLAND_ACT1_INTERLUDE1@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4600102
L10_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L11_1 = "NEWCOMER_NPC_DREAM_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "어쭈. 너 한 번 도와줬다고 아주 콧대가 하늘을 찌른다?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ちょっと。一度助けてたからってずいぶん偉そうじゃない？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Oh yeah? Being stuck-up just because you helped me out once?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "嘖嘖，才幫過我一次就在那邊拿翹？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "อ๋อเหรอ? ต้องมาติดแหง็กอยู่นี่เพราะพวกเธอช่วยฉันไว้ครั้งนึงเนี่ยนะ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Oh yeah? Bị mắc kẹt chỉ vì cậu đã giúp tôi một lần?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "哎呦——就因为帮了我一次忙，你们就觉得自己很行了？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ach ja? Reitest du etwa immer noch darauf herum, dass du mir einmal geholfen hast?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Hé ! Tout ça parce que vous m'avez filé un coup de main UNE fois ?"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "NEVERLAND_ACT1_INTERLUDE1@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4600102
L11_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_SERIOUS"
L12_1 = "HAVEN_HAVEN_NULL_ROOT"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L11_1.m_Crash = 20
L12_1 = "……에, 엔진실!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "……え、エンジンルーム！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "...Th-the engine room!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "……引…引擎室！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "หะ-ห้องเครื่องยนต์...!"
L11_1.m_Talk_THA = L12_1
L12_1 = "P-phòng máy...!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "……发、发动机舱！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "... D-der Maschinenraum!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "... L-La salle des machines !"
L11_1.m_Talk_FRA = L12_1
