L13_1 = "NEVERLAND_ACT1_INTERLUDE1@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 4600102
L12_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_IDLE"
L13_1 = "RUNNER_OZ_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "엔진실?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "エンジンルーム？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "What about it?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "引擎室？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มันทำไมเหรอ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nó thì sao?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "发动机舱？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Was ist damit?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Hein ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "NEVERLAND_ACT1_INTERLUDE1@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 4600102
L13_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SERIOUS"
L14_1 = "HAVEN_HAVEN_NULL_ROOT"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "그래, 엔진실로 가는 길을 알고 있어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そう、エンジンルームの行き方を知ってるよ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I know how to get there."
L13_1.m_Talk_ENG = L14_1
L14_1 = "對，我知道要怎麼去引擎室。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ผมรู้ทางไปนะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Tôi biết cách đến đó."
L13_1.m_Talk_VTN = L14_1
L14_1 = "是的，我知道怎么去发动机舱！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich weiß, wie man dorthin kommt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je sais comment faire pour y aller."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "NEVERLAND_ACT1_INTERLUDE1@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4600102
L14_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L15_1 = "NEWCOMER_NPC_DREAM_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "미안한데 그건 나도 알아."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "悪いけど、それは私も知ってる。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yeah? Well, so do I."
L14_1.m_Talk_ENG = L15_1
L15_1 = "不好意思，這我也知道。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เหรอ? ฉันก็รู้เหอะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Vậy à? Tôi cũng vậy."
L14_1.m_Talk_VTN = L15_1
L15_1 = "抱歉，那个我也知道。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ach ja? Tut mir leid, aber das weiß ich auch."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ah oui ? Ça tombe bien, moi aussi."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "NEVERLAND_ACT1_INTERLUDE1@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4600102
L15_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SURPRISE"
L16_1 = "HAVEN_HAVEN_NULL_ROOT"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L15_1.m_Crash = 25
L16_1 = "뭐? 네가 어떻게?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "え？　君がどうやって？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "What? But how?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "什麼？你怎麼會知道？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หา? รู้ได้ไงอ่ะ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Gì cơ? Nhưng bằng cách nào?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "什么？你怎么会知道？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Was? Aber wie?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Quoi ? Mais comment ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NEVERLAND_ACT1_INTERLUDE1@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4600102
L16_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "NEWCOMER_NPC_DREAM_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "그야 헤이븐 랜드에서 일하고 싶어서 밤을 새워가며 노력했으니까."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そりゃあ、ヘイブンランドで働きたくて徹夜もして頑張ってたからね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Because I pulled all-nighters working hard in hopes of working in Havenland."
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為我太想在天堂樂園工作，所以努力熬夜唸書。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เพราะฉันเคยต้องอดหลับอดนอนจำผังทั้งคืนเพราะหวังจะได้มาทำงานที่แฮฟเวนแลนด์นี่ไง"
L16_1.m_Talk_THA = L17_1
L17_1 = "Bởi vì tôi đã thức cả đêm để ghi nhớ toàn bộ bản đồ của Havenland trong đầu với hy vọng được làm việc ở đây."
L16_1.m_Talk_VTN = L17_1
L17_1 = "那是因为我之前很想去海文乐园工作，所以熬夜努力学习过。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Jeden Abend prägte ich mir den gesamten Grundriss von Havenland ein, in der Hoffnung, eines Tages hier arbeiten zu können."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Parce que j'ai mémorisé par cœur toute la carte de Havenland. Je rêvais de travailler ici..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "NEVERLAND_ACT1_INTERLUDE1@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4600102
L17_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_DESPAIR"
L18_1 = "NEWCOMER_NPC_DREAM_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "현실은 위저드에 처박혔고, 지금은 침입자 신세지만."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "現実はウィザード勤務だったし、今は侵入者になってるけど。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "But instead, I got stuck working at Wizard, and ended up sneaking into this place instead."
L17_1.m_Talk_ENG = L18_1
L18_1 = "結果卻被困在巫師裡，現在還變成侵入者。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แต่กลายเป็นต้องไปจมปลักอยู่กับวิซาร์ด แล้วก็ลงเอยด้วยการแอบเข้ามาที่นี่แทนเนี่ย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nhưng rồi, tôi bị kẹt ở Wizard, và cuối cùng lại lẻn vào nơi này."
L17_1.m_Talk_VTN = L18_1
L18_1 = "但现实是，之前被困在了巫师会，而现在是个入侵者。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Aber stattdessen blieb ich bei Wizard hängen und muss mich deshalb jetzt hier so einschleichen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Sauf qu'au lieu de ça, j'ai été forcée de travailler au Wizard. Et aujourd'hui, je me retrouve ici dans la peau d'un intrus."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "NEVERLAND_ACT1_INTERLUDE1@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4600102
L18_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_SERIOUS"
L19_1 = "HAVEN_HAVEN_NULL_ROOT"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "그래도 내가 더 자세히 알 걸? 내기라도 할래?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "でも、僕の方が詳しいよ。勝負する？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "But I think I still know this place better than you. Wanna bet?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "不過我知道的應該比你更詳細欸？要來打賭嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่ผมว่าผมก็ยังรู้จักที่นี่ดีกว่าเธออยู่ดีนะ พนันกันมั้ยล่ะ?"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nhưng tôi nghĩ rằng tôi vẫn biết rõ nơi này tốt hơn các cậu. Muốn cược không?"
L18_1.m_Talk_VTN = L19_1
L19_1 = "我、我知道得肯定比你详细……？要不要打个赌！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Aber ich glaube, ich kenne diesen Ort immer noch besser als du. Wollen wir wetten?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Je suis sûr que je connais mieux cet endroit que toi. Tu veux parier ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "NEVERLAND_ACT1_INTERLUDE1@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4600102
L19_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L20_1 = "NEWCOMER_NPC_DREAM_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "뭐래. 내가 얻는 것도 없는 내기를 왜 하냐?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "何だよ。なんの得もないのに、なんで私が？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "*Scoff* Why would I make a bet with you when there’s nothing I can gain if I win?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "你說什麼？我又得不到什麼好處，幹嘛要跟你賭？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "*เฮอะ* ฉันจะไปพนันทำไมในเมื่อชนะไปก็ไม่ได้อะไรนะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "*Chế giễu* Tôi cược với anh làm gì khi tôi chẳng có gì nếu thắng?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "说什么呢。我为什么要打这种一点好处都没有的赌？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "*Schmunzel* Warum sollte ich eine Wette mit dir abschließen, wenn ich dabei sowieso nichts gewinnen kann?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Peuh. Un pari ? Et qu'est-ce que j'ai à y gagner ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "NEVERLAND_ACT1_INTERLUDE1@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 4600102
L20_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L21_1 = "HAVEN_HAVEN_NULL_ROOT"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "네가 이기면 얌전히 입 다물어 줄게."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "君が勝ったら聞いたことは口外しない。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "All right. If you win, I'll keep my mouth shut."
L20_1.m_Talk_ENG = L21_1
L21_1 = "你贏的話，我就乖乖閉上嘴。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ก็ได้ ถ้าเธอชนะ ผมจะปิดปากเงียบไว้"
L20_1.m_Talk_THA = L21_1
L21_1 = "Được rồi. Nếu cô thắng, tôi sẽ ngậm miệng."
L20_1.m_Talk_VTN = L21_1
L21_1 = "你、你要是赢了，我就乖乖闭嘴。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "In Ordnung. Wenn du gewinnst, werde ich meinen Mund halten."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Si tu gagnes, je resterai muet comme une carpe."
