L21_1.m_Bounce = L22_1
L22_1 = "대신에 내가 이기면 같이 다녀도 되는 거다?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "その代わりに、僕が勝ったら一緒に行ってもいいよね？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "However, if I win, you have to let me tag along. Sound good?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "我贏的話，就讓我一起同行？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่ถ้าผมชนะ ต้องให้ผมไปด้วย เข้าท่าดีมั้ยล่ะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tuy nhiên, nếu tôi thắng, mọi người phải để tôi đi theo. Được chứ?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "相反，如果我赢了，你就同意我一起去，行吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wenn ich jedoch gewinne, darf ich mich euch offiziell anschließen. Was hältst du davon?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Et si c'est moi qui gagne... tu dois me laisser vous accompagner. Qu'est-ce que tu dis de ça ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
