L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "NEWCOMER_NPC_DREAM_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "호오, 그렇게 나오시겠다?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ほう、そう来たか。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Huh? So that's how it's going to be, eh?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "喔呵，要這樣是吧？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อ่อ... จะเอางั้นเหรอ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ooh... Vậy đó hả?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "吼吼，这就是你的要求是吧？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Oh, du willst es also wirklich darauf anlegen?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ooh... Je vois qu'on a un joueur !"
L22_1.m_Talk_FRA = L23_1
