L24_1 = "NEWCOMER_NPC_DREAM_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "좋아. 찍 소리도 못하게 해 주지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "いいよ。ぐうの音も出ないようにしてあげる。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "All right. It's your loss."
L23_1.m_Talk_ENG = L24_1
L24_1 = "好啊，我會讓你輸得心服口服！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ก็ได้ นายจะขาดทุนเองนะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Được rồi. Thế thì chỉ anh thiệt thôi."
L23_1.m_Talk_VTN = L24_1
L24_1 = "好，那我就让你输得心服口服。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Also gut. Du wirst schon noch sehen, was du davon hast."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Ok. Faudra pas venir te plaindre quand tu auras perdu."
L23_1.m_Talk_FRA = L24_1
