L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "……그냥 떼어 놓고 가도 되지 않아?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "……別に置いて行けばいいんじゃないかな？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "...Why don't we just leave him here?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "……就扔下他走人不就好了嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ทำไมเราไม่แค่ทิ้งๆ เขาไว้นี่นะคะ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tại sao chúng ta không để anh ta ở đây?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "其实……我们直接甩掉他再走也可以吧？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Warum lassen wir ihn nicht einfach hier zurück?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "... On peut pas juste le laisser ici ?"
