L28_1 = "PUPPET_NPC_SUPPLEMENT_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R_M_I"
L28_1 = "시그마. 작전은 잘 전달받았지? 암호가 어렵진 않았어?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "シグマ。作戦はちゃんと伝わってる？　暗号は難しくなかった？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Sigma. Did you get everything I sent you about the operation? Did you have any trouble with the encryption?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "西格瑪，你有收到作戰計畫吧？密碼會太難嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ซิกมา เธอได้ทุกอย่างเกี่ยวกับปฏิบัติการที่ฉันส่งไปให้มั้ยนะ? เธอมีปัญหาอะไรกับการเข้ารหัสรึเปล่า?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Sigma. Cậu đã nhận được mọi thứ tôi gửi cho cậu về tác chiến chưa? Cậu có gặp vấn đề gì với việc mã hóa không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "西格玛，作战计划，收到了吧？我加密了的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sigma. Hast du alles bekommen, was ich dir bezüglich der Operation geschickt habe? Hattest du Probleme mit der Verschlüsselung?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Sigma. Tu as bien reçu le briefing de l'opération ? Aucun problème avec le chiffrage des données ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "NEVERLAND_ACT1_INTERLUDE1@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4600102
L28_1.m_CutScenStrID = "NEVERLAND_ACT1_INTERLUDE1"
L28_1.m_bWaitClick = true
