L28_1.m_Face = "UNIT_SURPRISE"
L28_1.m_CharStrID = "SIGMA_RAS_NULL_NULL"
L28_1.m_Pos = "L"
L29_1 = "암호가 걸려 있었어? 그냥 슝 넘어갔는데."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "暗号がかけてあったの？　別に大丈夫だったよ？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Encryption? I didn't notice anything like that."
L28_1.m_Talk_ENG = L29_1
L29_1 = "有密碼嗎？就直接咻地通過咧？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เข้ารหัสเหรอ? ไม่เห็นมีอะไรแบบนั้นเลยนะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Mã hóa? Tôi chưa thấy bất cứ cái gì như thế."
L28_1.m_Talk_VTN = L29_1
L29_1 = "加密？我一下子就过去了呀。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Es gab eine Verschlüsselung? Davon habe ich nichts mitbekommen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Le chiffrage des données ? Je n'ai rien remarqué de tel."
L28_1.m_Talk_FRA = L29_1
