L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L30_1 = "어… 응. 쉽게 풀었으면 됐어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "あ……うん。簡単に解けたんならいいんだ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Oh... Okay. Good for you then."
L29_1.m_Talk_ENG = L30_1
L30_1 = "喔…有解開密碼就好。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อ้อ... โอเค งั้นก็ดีแล้ว"
L29_1.m_Talk_THA = L30_1
L30_1 = "Oh... được rồi. Tốt thôi."
L29_1.m_Talk_VTN = L30_1
L30_1 = "哦……嗯，破解了就好。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Oh, nun ja. Gut für dich, wenn du sie so einfach entschlüsseln konntest."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Oh... d'accord. Tant mieux, je suppose."
