L32_1 = "NEWCOMER_NPC_DREAM_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "이제 출발하자. 더 늦어지면 곤란해."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もう出発しよ。これ以上遅れたら困るから。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "C'mon. Let's go. We're losing time."
L31_1.m_Talk_ENG = L32_1
L32_1 = "事不宜遲，趕緊出發吧！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "มาเร็ว ไปกันเถอะ เสียเวลาแล้ว"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nào. Đi thôi. Mất thì giờ quá."
L31_1.m_Talk_VTN = L32_1
L32_1 = "现在出发吧。再晚就麻烦了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Kommt schon. Lasst uns gehen. Wir haben keine Zeit zu verlieren."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Allez, en route. On a déjà perdu assez de temps comme ça."
