L36_1 = "……黙ってついて来な。ナード。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "...All right, nerd. Be quiet and follow me."
L35_1.m_Talk_ENG = L36_1
L36_1 = "……這位先生，閉上你的嘴跟上。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอาล่ะตาเนิร์ด หุบปากแล้วตามมานะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Được rồi, mọt sách. Im lặng và đi theo tôi nào."
L35_1.m_Talk_VTN = L36_1
L36_1 = "……你闭嘴，安静地跟着，呆子。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Halt den Rand und folg mir einfach, du Nerd."
L35_1.m_Talk_DEU = L36_1
L36_1 = "... Silence, le weeb. Contente-toi de me suivre."
